{
  "tool": "machine_blast_radius",
  "args": {
    "machine": "build-box",
    "depth": 2
  },
  "outcome": "answered_with_path",
  "summary": "If \"build-box\" goes down: 1 project stops (\"Portfolio\") and \"refresh the portfolio theme\" (queued). Portfolio also lives on laptop (connected: true) — reported here; nothing is moved silently.",
  "rows": [
    {
      "isTask": false,
      "title": "Portfolio",
      "state": null,
      "via": [
        "build-box",
        "Portfolio"
      ],
      "nodeLabels": [
        "Project",
        "Project"
      ],
      "rels": [
        "OWNS"
      ],
      "hops": 1
    },
    {
      "isTask": true,
      "title": "refresh the portfolio theme",
      "state": "queued",
      "via": [
        "build-box",
        "Portfolio",
        "refresh the portfolio theme"
      ],
      "nodeLabels": [
        "Project",
        "Project",
        "Task"
      ],
      "rels": [
        "OWNS",
        "HAS"
      ],
      "hops": 2
    }
  ],
  "paths": [
    "(:Machine {name: \"build-box\"})-[:OWNS]->(:Project {title: \"Portfolio\"})",
    "(:Machine {name: \"build-box\"})-[:OWNS]->(:Project {title: \"Portfolio\"})-[:HAS]->(:Task {title: \"refresh the portfolio theme\", state: \"queued\"})",
    "(:Machine {name: \"laptop\"})-[:OWNS]->(:Project {title: \"Portfolio\"})   [mirror of \"build-box\"'s copy — connected: true]"
  ],
  "cypher": "MATCH path = (m:Machine {id: $machineId})-[:OWNS|HAS*1..2]->(x)\nRETURN 'Task' IN labels(x) AS isTask, coalesce(x.title, x.name) AS title, x.state AS state,\n       [n IN nodes(path) | coalesce(n.name, n.title)] AS via,\n       [n IN nodes(path) | CASE WHEN 'Task' IN labels(n) THEN 'Task' ELSE 'Project' END] AS nodeLabels,\n       [r IN relationships(path) | type(r)] AS rels,\n       length(path) AS hops\nORDER BY hops, title",
  "params": {
    "machineId": "machine-build-box"
  },
  "untrusted": true
}
